class ErroreDati(ValueError):
    pass

def leggi_utilizzo(testo):
    try:
        u = float(testo)
    except ValueError:
        raise ErroreDati(f"non è un numero: {testo}") from None
    if u < 0:
        raise ErroreDati(f"utilizzo negativo: {testo}")
    return u

def main(argv):
    try:
        u = leggi_utilizzo(argv[0])
    except ErroreDati:
        return 2
    return 0 if u <= 1 else 1

print(main(["0.85"]))
